<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessToken;

final class DcrInitialAccessTokenUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new DcrInitialAccessToken(
            uid: 'one',
            tenant: new TenantRef('one'),
            description: 'one',
            tokenHash: 'hmac-sha256:p1:cypher',
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            maxUses: 1,
            uses: 1,
            allowedGrantTypes: 'one',
            revokedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = DcrInitialAccessToken::calculatedFields();

        // @Assert
        $this->assertEquals([ 'uses'], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged());
        $this->assertEquals($one->getDescription(), $other->getDescription());
        $this->assertTrue($one->isDescriptionChanged());
        $this->assertEquals($one->getTokenHash(), $other->getTokenHash());
        $this->assertTrue($one->isTokenHashChanged());
        $this->assertEquals($one->getExpiresAt(), $other->getExpiresAt());
        $this->assertTrue($one->isExpiresAtChanged());
        $this->assertEquals($one->getMaxUses(), $other->getMaxUses());
        $this->assertTrue($one->isMaxUsesChanged());
        $this->assertEquals($one->getAllowedGrantTypes(), $other->getAllowedGrantTypes());
        $this->assertTrue($one->isAllowedGrantTypesChanged());
        $this->assertEquals($one->getRevokedAt(), $other->getRevokedAt());
        $this->assertTrue($one->isRevokedAtChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new DcrInitialAccessToken(
            uid: 'one',
            tenant: new TenantRef('one'),
            description: 'one',
            tokenHash: 'hmac-sha256:p1:cypher',
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            maxUses: 1,
            uses: 1,
            allowedGrantTypes: 'one',
            revokedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new DcrInitialAccessToken(
            uid: 'other',
            tenant: new TenantRef('other'),
            description: 'other',
            tokenHash: 'hmac-sha256:p1:ocyphered',
            expiresAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            maxUses: 2,
            uses: 2,
            allowedGrantTypes: 'other',
            revokedAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged($base));
        $this->assertEquals($one->getDescription(), $other->getDescription());
        $this->assertTrue($one->isDescriptionChanged($base));
        $this->assertEquals($one->getTokenHash(), $other->getTokenHash());
        $this->assertTrue($one->isTokenHashChanged($base));
        $this->assertEquals($one->getExpiresAt(), $other->getExpiresAt());
        $this->assertTrue($one->isExpiresAtChanged($base));
        $this->assertEquals($one->getMaxUses(), $other->getMaxUses());
        $this->assertTrue($one->isMaxUsesChanged($base));
        $this->assertEquals($one->getAllowedGrantTypes(), $other->getAllowedGrantTypes());
        $this->assertTrue($one->isAllowedGrantTypesChanged($base));
        $this->assertEquals($one->getRevokedAt(), $other->getRevokedAt());
        $this->assertTrue($one->isRevokedAtChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new DcrInitialAccessToken(
            uid: 'one',
            tenant: new TenantRef('one'),
            description: 'one',
            tokenHash: 'hmac-sha256:p1:cypher',
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            maxUses: 1,
            uses: 1,
            allowedGrantTypes: 'one',
            revokedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['tenant']['$ref']);
        $this->assertEquals('one', $json['description']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['expiresAt']);
        $this->assertEquals(1, $json['maxUses']);
        $this->assertEquals(1, $json['uses']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['revokedAt']);
        $this->assertEquals(1, $json['version']);
    }
